'use client';

import { useId, useState } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { formatTokens } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';

import { CompactOffer, contextAnnouncementOf } from './_parts/compact-offer';
import {
  freeTokensOf,
  LEVEL_WORD,
  levelOf,
  PART_FILL,
  RESERVE_STYLE,
  usedTokensOf,
  type Compaction,
  type ContextBudget,
  type ContextItem,
  type ContextSlot,
} from './_parts/context';
import { ContextHeader } from './_parts/context-header';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { TokenCount } from './_parts/token-count';
import {
  FILLING_SCRIPT,
  FILLING_SESSION,
  useContextSession,
  type CompactStatus,
  type ContextSession,
  type ContextStep,
} from './_parts/use-context-demo';

type CellKind = ContextSlot;

type LegendEntry = {
  kind: CellKind;
  label: string;
  tokens: number;
};

/** One cell holds a thousand tokens; a 200k context is a field of 10 rows of 20. */
const TOKENS_PER_CELL = 1000;

const FILL_STAGGER_MS = 14;

const FREE_FILL = 'color-mix(in oklab, var(--foreground) 6%, transparent)';

function fillOf(kind: Exclude<CellKind, 'reserve'>) {
  if (kind === 'free') {
    return FREE_FILL;
  }
  return PART_FILL[kind];
}

function cellStyleOf(kind: CellKind): React.CSSProperties {
  if (kind === 'reserve') {
    return RESERVE_STYLE;
  }
  return { backgroundColor: fillOf(kind) };
}

const DIMMED_PERCENT = 25;

const DIMMED_OPACITY = DIMMED_PERCENT / 100;

/**
 * A cell that steps back keeps a quarter of its colour. The colour itself fades, so two hundred
 * cells dim in one repaint of the field and none of them becomes a layer of its own.
 */
function dimmedCellStyleOf(kind: CellKind): React.CSSProperties {
  if (kind === 'reserve') {
    return { ...RESERVE_STYLE, opacity: DIMMED_OPACITY };
  }
  const fill = fillOf(kind);
  return {
    backgroundColor: `color-mix(in oklab, ${fill} ${DIMMED_PERCENT}%, transparent)`,
  };
}

function cellCountOf(tokens: number) {
  return Math.round(tokens / TOKENS_PER_CELL);
}

/** Parts fill cells in order, rounded on running totals so the field always adds up to the limit. */
function cellKindsOf(budget: ContextBudget) {
  const total = cellCountOf(budget.limit);
  const reserveCells = cellCountOf(budget.reserve);
  const freeEnd = total - reserveCells;
  const kinds: CellKind[] = [];
  let runningTokens = 0;
  for (const part of budget.parts) {
    runningTokens += part.tokens;
    const partEnd = cellCountOf(runningTokens);
    const boundary = Math.min(partEnd, freeEnd);
    while (kinds.length < boundary) {
      kinds.push(part.id);
    }
  }
  while (kinds.length < freeEnd) {
    kinds.push('free');
  }
  while (kinds.length < total) {
    kinds.push('reserve');
  }
  return kinds;
}

function isPartCell(kind: CellKind) {
  const isFree = kind === 'free';
  const isReserve = kind === 'reserve';
  return !isFree && !isReserve;
}

function filledCountOf(kinds: CellKind[]) {
  const filled = kinds.filter(isPartCell);
  return filled.length;
}

type FillHistory = { filled: number; previous: number };

function delayOf(index: number, history: FillHistory, isStaggered: boolean) {
  if (!isStaggered) {
    return 0;
  }
  const isNew = index >= history.previous;
  const isFilled = index < history.filled;
  if (isNew && isFilled) {
    const order = index - history.previous;
    return order * FILL_STAGGER_MS;
  }
  return 0;
}

function isDimmedCell(kind: CellKind, activeKind: CellKind | null) {
  if (activeKind === null) {
    return false;
  }
  return kind !== activeKind;
}

function useFillHistory(filled: number) {
  const [history, setHistory] = useState<FillHistory>({
    filled,
    previous: filled,
  });
  if (history.filled !== filled) {
    setHistory({ filled, previous: history.filled });
  }
  return history;
}

function legendOf(budget: ContextBudget): LegendEntry[] {
  const entries: LegendEntry[] = [];
  for (const part of budget.parts) {
    if (part.tokens > 0) {
      entries.push({ kind: part.id, label: part.label, tokens: part.tokens });
    }
  }
  const free = freeTokensOf(budget);
  entries.push({ kind: 'free', label: 'Free', tokens: free });
  entries.push({
    kind: 'reserve',
    label: 'Held for the answer',
    tokens: budget.reserve,
  });
  return entries;
}

function spokenFieldOf(budget: ContextBudget) {
  const used = usedTokensOf(budget);
  const usedText = formatTokens(used);
  const limitText = formatTokens(budget.limit);
  return `${usedText} of ${limitText} tokens used, one cell per thousand`;
}

function cellColorOf(kind: CellKind, isDimmed: boolean) {
  if (isDimmed) {
    return dimmedCellStyleOf(kind);
  }
  return cellStyleOf(kind);
}

function cellLookOf(
  kind: CellKind,
  index: number,
  history: FillHistory,
  isStaggered: boolean,
  isDimmed: boolean
): React.CSSProperties {
  const delay = delayOf(index, history, isStaggered);
  const color = cellColorOf(kind, isDimmed);
  return { ...color, transitionDelay: `${delay}ms` };
}

function CellField({
  budget,
  activeKind,
}: {
  budget: ContextBudget;
  activeKind: CellKind | null;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const kinds = cellKindsOf(budget);
  const filled = filledCountOf(kinds);
  const history = useFillHistory(filled);
  const isStaggered = !shouldReduceMotion;
  const spoken = spokenFieldOf(budget);

  return (
    <div role='img' aria-label={spoken} className='grid grid-cols-20 gap-0.5'>
      {kinds.map((kind, index) => (
        <span
          key={index}
          className='aspect-square rounded-[3px] transition-[background-color,opacity] duration-300 ease-(--ease-out-strong)'
          style={cellLookOf(
            kind,
            index,
            history,
            isStaggered,
            isDimmedCell(kind, activeKind)
          )}
        />
      ))}
    </div>
  );
}

function litRowOf(isLit: boolean) {
  if (isLit) {
    return 'bg-foreground/[0.03]';
  }
  return undefined;
}

function LegendButton({
  entry,
  isPinned,
  isLit,
  onPreview,
  onTogglePin,
}: {
  entry: LegendEntry;
  isPinned: boolean;
  /** Its cells are the ones lit now, whoever pointed at them. */
  isLit: boolean;
  onPreview: (kind: CellKind | null) => void;
  onTogglePin: (kind: CellKind) => void;
}) {
  function preview() {
    onPreview(entry.kind);
  }

  function clearPreview() {
    onPreview(null);
  }

  return (
    <button
      type='button'
      aria-pressed={isPinned}
      onPointerEnter={preview}
      onPointerLeave={clearPreview}
      onFocus={preview}
      onBlur={clearPreview}
      onClick={() => onTogglePin(entry.kind)}
      className={cn(
        'hover:bg-foreground/[0.03] focus-visible:ring-ring/25 aria-pressed:bg-foreground/[0.05] flex h-8 w-full cursor-pointer items-center gap-2.5 rounded-md px-2 text-start text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]',
        litRowOf(isLit)
      )}
    >
      <span
        aria-hidden='true'
        className='size-2.5 shrink-0 rounded-[3px]'
        style={cellStyleOf(entry.kind)}
      />
      <span className='min-w-0 flex-1 truncate'>{entry.label}</span>
      <TokenCount tokens={entry.tokens} className='text-muted-foreground' />
    </button>
  );
}

function barStyleOf(turn: ContextItem, maxTokens: number): React.CSSProperties {
  const share = turn.tokens / maxTokens;
  const height = Math.max(8, share * 100);
  return { height: `${height}%` };
}

function turnCountOf(count: number) {
  if (count === 1) {
    return '1 turn';
  }
  return `${count} turns`;
}

function maxTokensOf(turns: ContextItem[]) {
  let max = 1;
  for (const turn of turns) {
    max = Math.max(max, turn.tokens);
  }
  return max;
}

function turnFillOf(index: number, lastIndex: number, foldedTurns: number) {
  if (index < foldedTurns) {
    return 'bg-chart-4';
  }
  if (index === lastIndex) {
    return 'bg-chart-1';
  }
  return 'bg-foreground/20';
}

function TurnSparkline({
  turns,
  foldedTurns,
}: {
  turns: ContextItem[];
  foldedTurns: number;
}) {
  const maxTokens = maxTokensOf(turns);
  const lastIndex = turns.length - 1;

  return (
    <div className='flex flex-col gap-1.5'>
      <div className='flex items-baseline justify-between gap-3 text-xs'>
        <span className='text-muted-foreground'>Tokens added per turn</span>
        <span className='text-muted-foreground tabular-nums'>
          {turnCountOf(turns.length)}
        </span>
      </div>
      <div aria-hidden='true' className='flex h-8 items-end gap-0.5'>
        {turns.map((turn, index) => (
          <span
            key={turn.id}
            className={cn(
              'min-w-0 flex-1 origin-bottom rounded-t-[2px] transition-[background-color,scale] duration-300 ease-(--ease-out-strong) starting:scale-y-0',
              turnFillOf(index, lastIndex, foldedTurns)
            )}
            style={barStyleOf(turn, maxTokens)}
          />
        ))}
      </div>
      <div className='sr-only'>
        <table>
          <caption>Tokens added per turn</caption>
          <tbody>
            {turns.map((turn) => (
              <tr key={turn.id}>
                <th scope='row'>{turn.label}</th>
                <td>{formatTokens(turn.tokens)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/** What a person points at comes first, then what they pinned, then what was lit from outside. */
function activeKindOf(
  preview: CellKind | null,
  pinned: CellKind | null,
  spotlight: CellKind | null
) {
  if (preview !== null) {
    return preview;
  }
  if (pinned !== null) {
    return pinned;
  }
  return spotlight;
}

export type ContextCellsProps = {
  budget: ContextBudget;
  turns: ContextItem[];
  compaction?: Compaction | null;
  canCompact?: boolean;
  compactStatus?: CompactStatus;
  onCompact?: () => void;
  /** Lights the cells of one part from outside, for a demonstration or a control beside the field. */
  spotlight?: ContextSlot | null;
  /** Shows Compact held down, for a demonstration that presses it. */
  isCompactPressed?: boolean;
  className?: string;
};

export function ContextCells({
  budget,
  turns,
  compaction = null,
  canCompact = false,
  compactStatus = 'idle',
  onCompact,
  spotlight = null,
  isCompactPressed = false,
  className,
}: ContextCellsProps) {
  const [previewKind, setPreviewKind] = useState<CellKind | null>(null);
  const [pinnedKind, setPinnedKind] = useState<CellKind | null>(null);
  const titleId = useId();
  const legend = legendOf(budget);
  const activeKind = activeKindOf(previewKind, pinnedKind, spotlight);
  const foldedTurns = compaction?.foldedTurns ?? 0;

  function togglePin(kind: CellKind) {
    setPinnedKind((current) => {
      if (current === kind) {
        return null;
      }
      return kind;
    });
  }

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        'bg-card hairline-ring ring-border @container flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <ContextHeader budget={budget} titleId={titleId} />
      <CellField budget={budget} activeKind={activeKind} />
      <ul
        aria-label='Parts of the context, point at one to light its cells'
        className='-mx-2 grid grid-cols-1 gap-x-3 @md:grid-cols-2'
      >
        {legend.map((entry) => (
          <li key={entry.kind}>
            <LegendButton
              entry={entry}
              isPinned={pinnedKind === entry.kind}
              isLit={activeKind === entry.kind}
              onPreview={setPreviewKind}
              onTogglePin={togglePin}
            />
          </li>
        ))}
      </ul>
      <TurnSparkline turns={turns} foldedTurns={foldedTurns} />
      <CompactOffer
        budget={budget}
        canCompact={canCompact}
        compactStatus={compactStatus}
        compaction={compaction}
        onCompact={onCompact}
        isPressed={isCompactPressed}
      />
    </section>
  );
}

function spot(after: number, slot: ContextSlot | null): ContextStep {
  return { after, by: 'demo', action: { type: 'spotlight', slot } };
}

/** The demonstration points at each part in turn before the conversation goes on. */
const TOUR: ContextStep[] = [
  spot(1200, 'system'),
  spot(650, 'tools'),
  spot(650, 'files'),
  spot(650, 'conversation'),
  spot(650, 'free'),
  spot(900, null),
];

const SESSION: ContextSession = {
  ...FILLING_SESSION,
  script: [...TOUR, ...FILLING_SCRIPT],
};

/** A part lit by the demonstration lets go the moment a person takes over. */
function spotlightOf(isAutoplaying: boolean, spotlight: ContextSlot | null) {
  if (isAutoplaying) {
    return spotlight;
  }
  return null;
}

export default function Run06() {
  const {
    ref,
    isInView,
    isAutoplaying,
    canReplay,
    pressed,
    turns,
    budget,
    compaction,
    compactStatus,
    canCompact,
    spotlight,
    compact,
    replay,
  } = useContextSession(SESSION);
  const level = levelOf(budget);
  const announcement = contextAnnouncementOf(
    level,
    LEVEL_WORD[level],
    compaction
  );

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex min-h-[42.5rem] w-full max-w-[28rem] flex-col gap-2'
    >
      <ClockGate isActive={isInView}>
        <ContextCells
          budget={budget}
          turns={turns}
          compaction={compaction}
          canCompact={canCompact}
          compactStatus={compactStatus}
          onCompact={compact}
          spotlight={spotlightOf(isAutoplaying, spotlight)}
          isCompactPressed={pressed === 'compact'}
        />
      </ClockGate>
      <div className='flex h-7 items-center justify-end'>
        <ReplayButton
          isShown={canReplay}
          onReplay={replay}
          label='Replay the conversation'
        />
      </div>
      <LiveRegion message={spokenUnless(isAutoplaying, announcement)} />
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { formatTokens } from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon } from '@/registry/ndeko/lib/icons';

import {
  compactionLineOf,
  freeTokensOf,
  levelOf,
  type Compaction,
  type ContextBudget,
  type ContextLevel,
} from './context';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { risePresenceOf } from '@/registry/ndeko/lib/motion-presets';
import type { CompactStatus } from './use-context-demo';

const COMPACT_LABELS: Record<MorphState, string> = {
  idle: 'Compact',
  busy: 'Compacting',
  done: 'Compacted',
};

function morphStateOf(status: CompactStatus): MorphState {
  if (status === 'compacting') {
    return 'busy';
  }
  return 'idle';
}

function isOfferShown(
  level: ContextLevel,
  canCompact: boolean,
  status: CompactStatus
) {
  const isCompactSoon = level === 'compact';
  const isCompacting = status === 'compacting';
  const isAvailable = canCompact || isCompacting;
  return isCompactSoon && isAvailable;
}

function traceOf(compaction: Compaction | null, isOffered: boolean) {
  if (isOffered) {
    return null;
  }
  return compaction;
}

type CompactOfferProps = {
  budget: ContextBudget;
  canCompact: boolean;
  compactStatus: CompactStatus;
  compaction: Compaction | null;
  onCompact?: () => void;
  /** Shows Compact held down, for a demonstration that presses it. */
  isPressed?: boolean;
};

export function CompactOffer({
  budget,
  canCompact,
  compactStatus,
  compaction,
  onCompact,
  isPressed = false,
}: CompactOfferProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const risePresence = risePresenceOf(shouldReduceMotion);
  const level = levelOf(budget);
  const free = freeTokensOf(budget);
  const freeText = formatTokens(free);
  const isOffered = isOfferShown(level, canCompact, compactStatus);
  const trace = traceOf(compaction, isOffered);

  return (
    <AnimatePresence initial={false} mode='popLayout'>
      {isOffered && (
        <motion.div key='offer' className='@container' {...risePresence}>
          <div className='bg-warning/10 flex flex-col gap-2.5 rounded-lg p-3 @lg:flex-row @lg:items-center'>
            <p className='text-warning-foreground min-w-0 flex-1 text-xs leading-5'>
              {freeText} tokens left before the reserve. Fold the older turns
              into a summary to keep going.
            </p>
            <MorphButton
              type='button'
              size='sm'
              state={morphStateOf(compactStatus)}
              labels={COMPACT_LABELS}
              onClick={onCompact}
              className={pressedSolidOf(isPressed)}
            />
          </div>
        </motion.div>
      )}
      {trace && (
        <motion.p
          key='trace'
          className='text-muted-foreground flex items-center gap-2 text-xs'
          {...risePresence}
        >
          <CheckIcon className='text-success-foreground size-3.5' />
          {compactionLineOf(trace)}
        </motion.p>
      )}
    </AnimatePresence>
  );
}

export function contextAnnouncementOf(
  level: ContextLevel,
  levelWord: string,
  compaction: Compaction | null
) {
  if (compaction) {
    const line = compactionLineOf(compaction);
    return `${line}. Context: ${levelWord}`;
  }
  if (level === 'compact') {
    return `Context: ${levelWord}. Compact is available`;
  }
  return `Context: ${levelWord}`;
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  LEVEL_LABELS,
  LEVEL_TONE,
  LEVEL_WORD,
  levelOf,
  usedTokensOf,
  type ContextBudget,
} from './context';
import { TokenCount } from './token-count';

type ContextHeaderProps = {
  budget: ContextBudget;
  titleId: string;
  title?: string;
};

export function ContextHeader({
  budget,
  titleId,
  title = 'Context',
}: ContextHeaderProps) {
  const used = usedTokensOf(budget);
  const level = levelOf(budget);

  return (
    <header className='flex items-start justify-between gap-3'>
      <div className='min-w-0'>
        <h3 id={titleId} className='text-sm font-medium'>
          {title}
        </h3>
        <p
          className={cn(
            'text-xs transition-colors duration-200',
            LEVEL_TONE[level]
          )}
        >
          <WordRoll text={LEVEL_WORD[level]} labels={LEVEL_LABELS} />
        </p>
      </div>
      <p className='text-[13px] tabular-nums'>
        <TokenCount tokens={used} className='font-medium' />
        <span className='text-muted-foreground'>
          {' of '}
          <TokenCount tokens={budget.limit} />
        </span>
      </p>
    </header>
  );
}

import { hatchOf } from '@/registry/ndeko/lib/hatch';

export type ContextPartId =
  'system' | 'tools' | 'files' | 'summary' | 'conversation';

/** A place in the window: one of its parts, the room left, or what is held back for the answer. */
export type ContextSlot = ContextPartId | 'free' | 'reserve';

export type ContextItem = {
  id: string;
  label: string;
  tokens: number;
};

export type ContextPart = {
  id: ContextPartId;
  label: string;
  tokens: number;
  items: ContextItem[];
};

export type ContextBudget = {
  limit: number;
  /** Held back for the model's answer: never filled by the context. */
  reserve: number;
  parts: ContextPart[];
};

export type ContextLevel = 'room' | 'filling' | 'compact';

export type Compaction = {
  foldedTurns: number;
  summaryTokens: number;
};

export const CONTEXT_LIMIT = 200_000;

export const CONTEXT_RESERVE = 16_000;

/** Parts are parts of one whole, not entities: they take the chart ramp and a muted fill, never the series. */
export const PART_FILL: Record<ContextPartId, string> = {
  system: 'color-mix(in oklab, var(--muted-foreground) 30%, transparent)',
  tools: 'var(--chart-3)',
  files: 'var(--chart-2)',
  summary: 'var(--chart-4)',
  conversation: 'var(--chart-1)',
};

export const RESERVE_STYLE = {
  backgroundColor:
    'color-mix(in oklab, var(--muted-foreground) 8%, transparent)',
  backgroundImage: hatchOf('var(--muted-foreground)', 40),
};

export const LEVEL_WORD: Record<ContextLevel, string> = {
  room: 'Plenty of room',
  filling: 'Filling up',
  compact: 'Compact soon',
};

export const LEVEL_LABELS = [
  LEVEL_WORD.room,
  LEVEL_WORD.filling,
  LEVEL_WORD.compact,
];

export const LEVEL_TONE: Record<ContextLevel, string> = {
  room: 'text-muted-foreground',
  filling: 'text-foreground',
  compact: 'text-warning-foreground',
};

const FILLING_FROM = 0.6;

const COMPACT_FROM = 0.85;

/** The newest turns stay word for word after a compaction. */
const KEPT_TURNS = 2;

const SUMMARY_SHARE = 0.08;

export const SYSTEM_ITEMS: ContextItem[] = [
  { id: 'system-prompt', label: 'System prompt', tokens: 4_100 },
  { id: 'system-notes', label: 'Saved notes', tokens: 2_100 },
];

export const TOOL_ITEMS: ContextItem[] = [
  { id: 'tool-search', label: 'web_search results', tokens: 1_900 },
  { id: 'tool-page', label: 'fetch_page result', tokens: 2_300 },
  { id: 'tool-sheet', label: 'read_sheet rows', tokens: 2_600 },
  { id: 'tool-script', label: 'run_script output', tokens: 1_800 },
];

export const FILE_ITEMS: ContextItem[] = [
  { id: 'file-invoices', label: 'q3-invoices.xlsx', tokens: 21_400 },
  { id: 'file-contract', label: 'brightmoor-contract.pdf', tokens: 18_600 },
  { id: 'file-pricing', label: 'pricing-page.html', tokens: 9_800 },
  { id: 'file-notes', label: 'vendor-notes.md', tokens: 3_100 },
];

const TURN_TOKENS = [
  5_200, 7_400, 9_800, 6_100, 12_400, 8_300, 10_900, 7_700, 13_600, 9_200,
  11_800, 8_600,
];

function turnOf(tokens: number, index: number): ContextItem {
  const number = index + 1;
  return { id: `turn-${number}`, label: `Turn ${number}`, tokens };
}

export const TURNS: ContextItem[] = TURN_TOKENS.map(turnOf);

export function sumTokens(items: readonly { tokens: number }[]) {
  let total = 0;
  for (const item of items) {
    total += item.tokens;
  }
  return total;
}

/** What the run holds before any conversation: system, tools and every file. */
const SYSTEM_TOKENS = sumTokens(SYSTEM_ITEMS);

const TOOL_TOKENS = sumTokens(TOOL_ITEMS);

const FILE_TOKENS = sumTokens(FILE_ITEMS);

export const BASE_TOKENS = SYSTEM_TOKENS + TOOL_TOKENS + FILE_TOKENS;

export function usedTokensOf(budget: ContextBudget) {
  return sumTokens(budget.parts);
}

export function freeTokensOf(budget: ContextBudget) {
  const used = usedTokensOf(budget);
  const free = budget.limit - budget.reserve - used;
  return Math.max(0, free);
}

export function shareOf(tokens: number, budget: ContextBudget) {
  return tokens / budget.limit;
}

export function percentOf(tokens: number, budget: ContextBudget) {
  const share = shareOf(tokens, budget);
  return share * 100;
}

export function levelOf(budget: ContextBudget): ContextLevel {
  const used = usedTokensOf(budget);
  const share = shareOf(used, budget);
  if (share < FILLING_FROM) {
    return 'room';
  }
  if (share <= COMPACT_FROM) {
    return 'filling';
  }
  return 'compact';
}

export function turnsWithin(conversationTokens: number) {
  const turns: ContextItem[] = [];
  let total = 0;
  for (const turn of TURNS) {
    const next = total + turn.tokens;
    if (next > conversationTokens) {
      break;
    }
    turns.push(turn);
    total = next;
  }
  return turns;
}

/** The tokens of the turns a compaction folds away: every turn of the conversation but the newest ones. */
export function foldableTokensOf(budget: ContextBudget) {
  const conversation = budget.parts.find((part) => part.id === 'conversation');
  if (!conversation) {
    return 0;
  }
  const foldedCount = conversation.items.length - KEPT_TURNS;
  if (foldedCount < 1) {
    return 0;
  }
  const folded = conversation.items.slice(0, foldedCount);
  return sumTokens(folded);
}

export function compactionOf(turns: ContextItem[]): Compaction | null {
  const foldedTurns = turns.length - KEPT_TURNS;
  if (foldedTurns < 2) {
    return null;
  }
  const folded = turns.slice(0, foldedTurns);
  const foldedTokens = sumTokens(folded);
  const rawSummary = foldedTokens * SUMMARY_SHARE;
  const summaryHundreds = Math.round(rawSummary / 100);
  const summaryTokens = summaryHundreds * 100;
  return { foldedTurns, summaryTokens };
}

function partOf(
  id: ContextPartId,
  label: string,
  items: ContextItem[]
): ContextPart {
  return { id, label, tokens: sumTokens(items), items };
}

function turnCountOf(count: number) {
  if (count === 1) {
    return '1 turn';
  }
  return `${count} turns`;
}

type BudgetInput = {
  turns: ContextItem[];
  removedFileIds: readonly string[];
  compaction: Compaction | null;
};

export function budgetOf({
  turns,
  removedFileIds,
  compaction,
}: BudgetInput): ContextBudget {
  const files = FILE_ITEMS.filter((file) => !removedFileIds.includes(file.id));
  const foldedCount = compaction?.foldedTurns ?? 0;
  const liveTurns = turns.slice(foldedCount);
  const parts: ContextPart[] = [
    partOf('system', 'System', SYSTEM_ITEMS),
    partOf('tools', 'Tools', TOOL_ITEMS),
    partOf('files', 'Files', files),
  ];
  if (compaction) {
    const summaryLabel = `Summary of ${turnCountOf(compaction.foldedTurns)}`;
    const summary = {
      id: 'summary',
      label: summaryLabel,
      tokens: compaction.summaryTokens,
    };
    parts.push(partOf('summary', 'Summary', [summary]));
  }
  parts.push(partOf('conversation', 'Conversation', liveTurns));
  return { limit: CONTEXT_LIMIT, reserve: CONTEXT_RESERVE, parts };
}

export function compactionLineOf(compaction: Compaction) {
  const turns = turnCountOf(compaction.foldedTurns);
  const thousands = compaction.summaryTokens / 1000;
  const summary = `${thousands.toFixed(1)}k`;
  return `Folded ${turns} into a ${summary} summary`;
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';

const THOUSANDS: Intl.NumberFormatOptions = { maximumFractionDigits: 1 };

type TokenCountProps = {
  tokens: number;
  className?: string;
};

export function TokenCount({ tokens, className }: TokenCountProps) {
  const thousands = tokens / 1000;
  return (
    <MotionNumber
      value={thousands}
      format={THOUSANDS}
      suffix='k'
      className={className}
    />
  );
}

'use client';

import {
  useSession,
  type SessionConfig,
  type SessionStep,
} from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';

import {
  budgetOf,
  compactionOf,
  TURNS,
  type Compaction,
  type ContextSlot,
} from './context';

export type CompactStatus = 'idle' | 'compacting';

const COMPACT_MS = 900;

/** An offer that waits on a person is taken by the demonstration after this long. */
const COMPACT_AFTER_MS = 2500;

export type ContextState = {
  /** How many turns of the conversation the context holds. */
  turnCount: number;
  removedFileIds: string[];
  compaction: Compaction | null;
  compactStatus: CompactStatus;
  /** The part a demonstration points at, in the views that light one part. */
  spotlight: ContextSlot | null;
  /** Whether the breakdown is open, in the views that fold it. */
  isBreakdownOpen: boolean;
};

export type ContextAction =
  | { type: 'turn' }
  | { type: 'removeFile'; fileId: string }
  | { type: 'compact' }
  | { type: 'compacted' }
  | { type: 'spotlight'; slot: ContextSlot | null }
  | { type: 'breakdown'; isOpen: boolean };

export type ContextStep = SessionStep<ContextState, ContextAction>;

export type ContextSession = SessionConfig<ContextState, ContextAction>;

export function contextStateAt(turnCount: number): ContextState {
  return {
    turnCount,
    removedFileIds: [],
    compaction: null,
    compactStatus: 'idle',
    spotlight: null,
    isBreakdownOpen: false,
  };
}

function turnsIn(state: ContextState) {
  return TURNS.slice(0, state.turnCount);
}

/** Compact is offered again only once new turns can be folded into the summary. */
function canCompactIn(state: ContextState) {
  const turns = turnsIn(state);
  const next = compactionOf(turns);
  const foldedNow = state.compaction?.foldedTurns ?? 0;
  const foldableNext = next?.foldedTurns ?? 0;
  const hasNewTurnsToFold = foldableNext > foldedNow;
  const isIdle = state.compactStatus === 'idle';
  return hasNewTurnsToFold && isIdle;
}

function withTurn(state: ContextState): ContextState {
  const hasMore = state.turnCount < TURNS.length;
  if (!hasMore) {
    return state;
  }
  return { ...state, turnCount: state.turnCount + 1 };
}

function withFileRemoved(state: ContextState, fileId: string): ContextState {
  const removedFileIds = [...state.removedFileIds, fileId];
  return { ...state, removedFileIds };
}

function withCompactStarted(state: ContextState): ContextState {
  if (!canCompactIn(state)) {
    return state;
  }
  return { ...state, compactStatus: 'compacting' };
}

/** The script and the hand of a person may both land the same compaction: only the first one counts. */
function withCompactLanded(state: ContextState): ContextState {
  if (state.compactStatus !== 'compacting') {
    return state;
  }
  const turns = turnsIn(state);
  const compaction = compactionOf(turns);
  return { ...state, compaction, compactStatus: 'idle' };
}

export function reduceContext(
  state: ContextState,
  action: ContextAction
): ContextState {
  switch (action.type) {
    case 'turn':
      return withTurn(state);
    case 'removeFile':
      return withFileRemoved(state, action.fileId);
    case 'compact':
      return withCompactStarted(state);
    case 'compacted':
      return withCompactLanded(state);
    case 'spotlight':
      return { ...state, spotlight: action.slot };
    case 'breakdown':
      return { ...state, isBreakdownOpen: action.isOpen };
  }
}

function hasCompacted(state: ContextState) {
  const isCompacting = state.compactStatus === 'compacting';
  const isCompacted = state.compaction !== null;
  return isCompacting || isCompacted;
}

/** A turn that arrives on its own: the conversation going on, which always plays. */
export function turnStep(after: number): ContextStep {
  return { after, action: { type: 'turn' } };
}

/** A message a person sends: the demonstration presses Send for them until they take over. */
export function sendStep(after: number, turnCount: number): ContextStep {
  return {
    after,
    by: 'person',
    press: 'send',
    action: { type: 'turn' },
    isAnswered: (state) => state.turnCount >= turnCount,
  };
}

/** Compact pressed by the demonstration once it is offered, then the summary landing. */
export const COMPACT_STEPS: ContextStep[] = [
  {
    after: COMPACT_AFTER_MS,
    by: 'person',
    press: 'compact',
    action: { type: 'compact' },
    isAnswered: hasCompacted,
  },
  { after: COMPACT_MS, action: { type: 'compacted' } },
];

/** The demos open on a conversation already under way and fill it one turn at a time. */
const OPENING_TURNS = 5;

const TURN_EVERY_MS = 900;

function arrivingTurns(): ContextStep[] {
  const count = TURNS.length - OPENING_TURNS;
  return Array.from({ length: count }, () => turnStep(TURN_EVERY_MS));
}

/** The conversation fills until Compact is offered, the demonstration takes it and the summary lands. */
export const FILLING_SCRIPT: ContextStep[] = [
  ...arrivingTurns(),
  ...COMPACT_STEPS,
];

/**
 * Under reduced motion nothing plays: the context rests full, with Compact on offer, which a person
 * can still take.
 */
export const FILLING_SESSION: ContextSession = {
  reducer: reduceContext,
  initial: contextStateAt(OPENING_TURNS),
  resting: contextStateAt(TURNS.length),
  script: FILLING_SCRIPT,
  loopAfter: 3400,
};

/** A context that fills turn by turn, played as a session: turns arrive, a person removes files and compacts. */
export function useContextSession(session: ContextSession) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(session);
  const { schedule, clearAll } = useTimeouts();
  const turns = turnsIn(state);
  const { removedFileIds, compaction } = state;
  const budget = budgetOf({ turns, removedFileIds, compaction });
  const budgetBefore = budgetOf({ turns, removedFileIds, compaction: null });
  const canCompact = canCompactIn(state);
  const canReplay = isFinished && !isAutoplaying;

  function removeFile(fileId: string) {
    act({ type: 'removeFile', fileId });
  }

  function compact() {
    if (!canCompact) {
      return;
    }
    act({ type: 'compact' });
    schedule(() => act({ type: 'compacted' }), COMPACT_MS);
  }

  function send() {
    act({ type: 'turn' });
  }

  function setBreakdownOpen(isOpen: boolean) {
    act({ type: 'breakdown', isOpen });
  }

  function replay() {
    clearAll();
    restart();
  }

  return {
    ref,
    isInView,
    isAutoplaying,
    canReplay,
    pressed,
    turns,
    budget,
    budgetBefore,
    compaction,
    compactStatus: state.compactStatus,
    canCompact,
    spotlight: state.spotlight,
    isBreakdownOpen: state.isBreakdownOpen,
    removeFile,
    compact,
    send,
    setBreakdownOpen,
    replay,
  };
}
